    for p in Producto.objects.select_related("categoria"):
        categoria = p.categoria.nombre
        p.opciones = "\n".join(OPCIONES.get(categoria, []))
        p.minutos_preparacion = MINUTOS.get(p.nombre, MINUTOS.get(categoria, 10))
        p.save(update_fields=["opciones", "minutos_preparacion"])


